#!/usr/bin/env python3
"""Feed exact byte lines to tspin, show escaped output.
Usage: probe.py [--args "..."]  ; reads lines (python string literals allowed via -r raw) from stdin
"""
import subprocess, sys

def run(lines, args=None, raw=False):
    """lines: list of str (unicode). args: list of CLI args."""
    if args is None:
        args = ['--disable-builtin-keywords']
    cmd = ['/workspace/executable', '-p'] + args
    data = ''.join(l + '\n' for l in lines).encode('utf-8', 'surrogateescape')
    p = subprocess.run(cmd, input=data, capture_output=True)
    out = p.stdout.decode('utf-8', 'surrogateescape')
    return out, p.stderr.decode('utf-8','replace'), p.returncode

def vis(s):
    return s.replace('\x1b', 'E')

if __name__ == '__main__':
    import argparse
    ap = argparse.ArgumentParser()
    ap.add_argument('--args', default='--disable-builtin-keywords')
    ap.add_argument('--eval', action='store_true', help='treat each input line as a python expression')
    a = ap.parse_args()
    args = a.args.split() if a.args.strip() else []
    lines = sys.stdin.read().split('\n')
    if lines and lines[-1] == '':
        lines.pop()
    if a.eval:
        lines = [eval(l) for l in lines]
    out, err, rc = run(lines, args)
    olines = out.split('\n')
    if olines and olines[-1] == '':
        olines.pop()
    for i, o in enumerate(olines):
        inp = lines[i] if i < len(lines) else '<extra>'
        print(f'{vis(inp)!r:60s} => {vis(o)!r}')
    if err:
        print('STDERR:', err, file=sys.stderr)
    if rc:
        print('RC:', rc, file=sys.stderr)

